.vibe-profile {position: relative; min-height: 100vh; background: #000; color: #00ff41; font-family: "IBM Plex Mono", "Courier New", monospace; overflow: hidden; padding: 40px 24px; box-sizing: border-box;}
.vibe-profile * {box-sizing: border-box;}
.vibe-profile .vibe-fx {position: absolute; inset: 0; pointer-events: none; overflow: hidden;}
.vibe-profile .scanlines {position: absolute; inset: 0; background: repeating-linear-gradient(0deg, rgba(0,255,65,0.08) 0px, rgba(0,255,65,0.08) 2px, rgba(0,0,0,0.1) 3px, rgba(0,0,0,0.1) 4px); mix-blend-mode: screen; opacity: 0.7;}
.vibe-profile .grid-glow {position: absolute; inset: -50%; background: radial-gradient(circle at 30% 30%, rgba(0,255,65,0.25), transparent 35%), radial-gradient(circle at 80% 10%, rgba(0,255,65,0.2), transparent 45%), radial-gradient(circle at 60% 80%, rgba(0,255,65,0.15), transparent 50%); filter: blur(60px);}
.vibe-profile .matrix-rain {position: absolute; inset: 0; display: grid; grid-template-columns: repeat(10, 1fr); gap: 2vw; opacity: 0.25;}
.vibe-profile .matrix-rain span {display: block; width: 2px; height: 120vh; background: linear-gradient(180deg, transparent, #00ff41, transparent); animation: fall 6s linear infinite; opacity: 0.8;}
.vibe-profile .matrix-rain span:nth-child(odd) {animation-duration: 4.5s;}
.vibe-profile .matrix-rain span:nth-child(even) {animation-duration: 7s;}
.vibe-profile .glare {position: absolute; inset: -10%; background: conic-gradient(from 90deg, rgba(0,255,65,0.05), rgba(0,0,0,0.1), rgba(0,255,65,0.05)); mix-blend-mode: screen; animation: rotateGlare 14s linear infinite;}
.vibe-profile .vibe-content {position: relative; max-width: 1100px; margin: 0 auto; padding: 24px; border: 1px solid rgba(0,255,65,0.3); background: linear-gradient(145deg, rgba(0,15,0,0.8), rgba(0,0,0,0.9)); box-shadow: 0 0 30px rgba(0,255,65,0.15), inset 0 0 20px rgba(0,255,65,0.1); backdrop-filter: blur(4px);}
.vibe-profile .hero {text-align: left; margin-bottom: 32px; position: relative; padding-bottom: 12px; border-bottom: 1px solid rgba(0,255,65,0.25);}
.vibe-profile .name {font-size: 48px; letter-spacing: 0.08em; margin: 0; text-transform: uppercase; text-shadow: 0 0 8px rgba(0,255,65,0.6), 0 0 16px rgba(0,255,65,0.4); position: relative; z-index: 2;}
.vibe-profile .title-glitch {position: absolute; top: 0; left: 0; font-size: 48px; letter-spacing: 0.08em; color: #00ff41; text-shadow: -2px 0 rgba(0,255,65,0.6), 2px 0 rgba(0,255,65,0.3); mix-blend-mode: screen; animation: glitch 2s infinite; opacity: 0.6;}
.vibe-profile .bio {margin: 8px 0 0; font-size: 16px; color: #7aff95; letter-spacing: 0.04em;}
.vibe-profile .shop {margin-top: 28px;}
.vibe-profile .shop-title {font-size: 14px; letter-spacing: 0.2em; margin-bottom: 14px; color: #00ff41; opacity: 0.9; text-transform: uppercase;}
.vibe-profile .items {display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 16px;}
.vibe-profile .card {position: relative; padding: 16px; border: 1px solid rgba(0,255,65,0.4); background: linear-gradient(180deg, rgba(0,255,65,0.05), rgba(0,255,65,0.01)); box-shadow: 0 0 12px rgba(0,255,65,0.2); transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease; overflow: hidden;}
.vibe-profile .card::after {content: ""; position: absolute; inset: 0; background: linear-gradient(120deg, transparent, rgba(0,255,65,0.2), transparent); transform: translateX(-100%); animation: sweep 3.5s linear infinite; opacity: 0.3;}
.vibe-profile .card:hover {transform: translateY(-4px) scale(1.01); box-shadow: 0 0 18px rgba(0,255,65,0.35); border-color: #00ff41;}
.vibe-profile .card-title {font-size: 18px; margin-bottom: 8px; color: #00ff41; letter-spacing: 0.05em;}
.vibe-profile .price {font-size: 16px; color: #7aff95; letter-spacing: 0.08em;}
.vibe-profile .foot {margin-top: 28px; font-size: 12px; letter-spacing: 0.1em; color: #00ff41; text-align: right; opacity: 0.8; border-top: 1px solid rgba(0,255,65,0.2); padding-top: 10px;}

@keyframes glitch {0%, 20%, 100% {transform: translate(0,0);}10% {transform: translate(-3px,-2px);}30% {transform: translate(2px,1px);}50% {transform: translate(-2px,2px);}70% {transform: translate(3px,-1px);}90% {transform: translate(-1px,3px);}}
@keyframes fall {0% {transform: translateY(-120%);}100% {transform: translateY(0%);}}
@keyframes rotateGlare {0% {transform: rotate(0deg);}100% {transform: rotate(360deg);}}
@keyframes sweep {0% {transform: translateX(-120%);}100% {transform: translateX(120%);}}
